// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 amount, uint256 blockNum, uint256 warpTime1, uint256 warpTime2, uint256 fuzzRoll) public {
        vm.assume(caller != address(0));
        vm.assume(amount == 10 ether);
        vm.assume(warpTime1 > 0);
        vm.assume(warpTime2 > warpTime1);
        blockNum = bound(blockNum, 1, type(uint256).max);
        warpTime1 = bound(warpTime1, 1, type(uint64).max);
        warpTime2 = bound(warpTime2, warpTime1 + 1, type(uint64).max);
        fuzzRoll = bound(fuzzRoll, 1, type(uint256).max);

        vm.deal(caller, 100 ether);
        vm.warp(warpTime1);
        vm.roll(blockNum);

        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first fallback reverted");

        assertTrue(c.pastBlockTime() == block.timestamp, "invariant: pastBlockTime should equal block timestamp after call");
    }
}
